"use client";

import Link from "next/link";
import { useEffect, useState, type FormEvent } from "react";

type DocumentItem = {
  id: number;
  title: string;
  content: string;
};

const API_BASE = "http://127.0.0.1:8001";

export default function Home() {
  const [documents, setDocuments] = useState<DocumentItem[]>([]);
  const [query, setQuery] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    loadDocuments();
  }, []);

  async function loadDocuments() {
    try {
      const response = await fetch(`${API_BASE}/documents`);
      if (!response.ok) {
        throw new Error("Failed to load documents");
      }
      const data = await response.json();
      setDocuments(data);
      setError("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unexpected error");
    }
  }

  async function handleSearch(event: FormEvent) {
    event.preventDefault();
    try {
      const response = await fetch(`${API_BASE}/search?q=${encodeURIComponent(query)}`);
      if (!response.ok) {
        throw new Error("Search failed");
      }
      const data = await response.json();
      setDocuments(data);
      setError("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unexpected error");
    }
  }

  return (
    <main style={{ minHeight: "100vh", padding: "1rem" }}>
      <nav style={{ display: "flex", gap: "1rem", marginBottom: "2rem" }}>
        <Link href="/">Home</Link>
        <Link href="/about">About</Link>
      </nav>

      <div style={{ maxWidth: "800px", margin: "0 auto" }}>
        <h1>Document Viewer</h1>
        <p>Search the stored documents from the Python backend.</p>

        <form onSubmit={handleSearch} style={{ display: "flex", gap: "0.5rem", marginBottom: "1rem" }}>
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search documents"
            style={{ flex: 1, padding: "0.5rem" }}
          />
          <button type="submit">Search</button>
        </form>

        <button onClick={loadDocuments} style={{ marginBottom: "1rem" }}>
          Show all documents
        </button>

        {error ? <p style={{ color: "crimson" }}>{error}</p> : null}

        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th style={{ borderBottom: "1px solid #ddd", textAlign: "left", padding: "0.5rem" }}>Title</th>
              <th style={{ borderBottom: "1px solid #ddd", textAlign: "left", padding: "0.5rem" }}>Content</th>
            </tr>
          </thead>
          <tbody>
            {documents.map((document) => (
              <tr key={document.id}>
                <td style={{ borderBottom: "1px solid #ddd", padding: "0.5rem" }}>{document.title}</td>
                <td style={{ borderBottom: "1px solid #ddd", padding: "0.5rem" }}>{document.content}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </main>
  );
}
